      q('[data-fxchip]').forEach(b=>b.onclick=()=>{ S.chip=b.dataset.fxchip; S.kpi=''; save(); draw(); });
      q('[data-fxdd]').forEach(s=>s.onchange=()=>{ S.f[s.dataset.fxdd]=s.value; save(); draw(); });
