      q('[data-fxrow]').forEach(tr=>tr.onclick=e=>{ if(e.target.closest('a,button:not([data-fxopen]),[data-fxsel],[data-ocust],[data-osupp],[data-operson]')) return; const r=L.find(z=>cfg.key(z)===tr.dataset.fxrow); if(r&&cfg.panel) cfg.panel(r,draw); });
      q('[data-fxopen]').forEach(b=>b.onclick=e=>{ e.stopPropagation(); const r=L.find(z=>cfg.key(z)===b.dataset.fxopen); if(r&&cfg.panel) cfg.panel(r,draw); });
